import sys
from collections import defaultdict

MOD = 10**9 + 9

def factorial(n):
    result = 1
    for i in range(2, n + 1):
        result = (result * i) % MOD
    return result

def mod_inverse(a, m):
    m0, x0, x1 = m, 0, 1
    if m == 1:
        return 0
    while a > 1:
        # q is quotient
        q = a // m
        m, a = a % m, m
        x0, x1 = x1 - q * x0, x0
    # Make x1 positive
    if x1 < 0:
        x1 += m0
    return x1

def count_permutations(n, freqs):
    total_permutations = factorial(n)
    for freq in freqs.values():
        total_permutations = (total_permutations * mod_inverse(factorial(freq), MOD)) % MOD
    return total_permutations

def main():
